/**
 * Admin contracts: provisioning of tables and customers.
 *
 * These endpoints live under `/api/v1/admin/tables` and `/api/v1/admin/customers`
 * and need a session of an account with the `admin` role
 * (`Authorization: Bearer <accessToken>`).
 *
 * A table's id is generated by the server and cannot be chosen or changed by
 * the caller, so the create and update requests carry no `id`.
 */

import { z } from 'zod';
import { accountDisplayNameSchema, authAccountSchema, emailSchema } from './auth.js';
import { planSchema } from './entitlements.js';
import { pairingLinkSchema, pairingTokenSchema } from './pairing.js';
import { tableIdSchema } from './table.js';

/** Fields an admin can set on a table. Shared by create and update. */
const displayNameSchema = z.string().trim().min(1).max(100);
const locationSchema = z.string().trim().min(1).max(200);
/**
 * The customer who ordered the table, or `null` for none. Only that customer
 * (and admins) can see or use the table. Must name an existing, non-disabled
 * customer account, which the API checks.
 */
const ownerAccountIdSchema = z.string().min(1).max(100).nullable();

/**
 * A table as stored: the registration record, without live state.
 *
 * Mode, connection and the active job come from the driver and are exposed by
 * the public `Table` resource instead.
 */
export const adminTableSchema = z.object({
  id: tableIdSchema,
  displayName: displayNameSchema,
  location: locationSchema,
  enabled: z.boolean(),
  // Defaults, so a tables file written before orders existed still loads.
  ownerAccountId: z.string().nullable().default(null),
  plan: planSchema.default('basic'),
  voiceAssistant: z.boolean().default(false),
  createdAt: z.string(),
  updatedAt: z.string(),
});
export type AdminTable = z.infer<typeof adminTableSchema>;

/** Body of `POST /api/v1/admin/tables`. */
export const createTableRequestSchema = z.object({
  displayName: displayNameSchema,
  location: locationSchema,
  /** A new table is enabled unless the admin says otherwise. */
  enabled: z.boolean().default(true),
  ownerAccountId: ownerAccountIdSchema.default(null),
  plan: planSchema.default('basic'),
  voiceAssistant: z.boolean().default(false),
});
export type CreateTableRequest = z.input<typeof createTableRequestSchema>;

/** Payload of `POST /api/v1/admin/tables` (`201`). */
export const createTableResponseSchema = adminTableSchema;
export type CreateTableResponse = AdminTable;

/** Payload of `GET /api/v1/admin/tables`. */
export const listAdminTablesResponseSchema = z.object({
  tables: z.array(adminTableSchema),
});
export type ListAdminTablesResponse = z.infer<typeof listAdminTablesResponseSchema>;

/** Payload of `GET /api/v1/admin/tables/:tableId`. */
export const getAdminTableResponseSchema = adminTableSchema;
export type GetAdminTableResponse = AdminTable;

/**
 * Body of `PATCH /api/v1/admin/tables/:tableId`.
 *
 * Every field is optional but at least one must be present, so an empty patch
 * is a validation error rather than a silent no-op. Unknown keys, including
 * `id`, are stripped.
 */
export const updateTableRequestSchema = z
  .object({
    displayName: displayNameSchema.optional(),
    location: locationSchema.optional(),
    enabled: z.boolean().optional(),
    /** `null` removes the owner. */
    ownerAccountId: ownerAccountIdSchema.optional(),
    plan: planSchema.optional(),
    voiceAssistant: z.boolean().optional(),
  })
  .refine((patch) => Object.values(patch).some((value) => value !== undefined), {
    message:
      'Provide at least one of displayName, location, enabled, ownerAccountId, plan or voiceAssistant.',
  });
export type UpdateTableRequest = z.infer<typeof updateTableRequestSchema>;

/** Payload of `PATCH /api/v1/admin/tables/:tableId`: the updated table. */
export const updateTableResponseSchema = adminTableSchema;
export type UpdateTableResponse = AdminTable;

/**
 * Payload of `GET /api/v1/admin/tables/:tableId/qr`.
 *
 * `link` is what the QR code encodes: `https://<domain>/t/<tableId>` in
 * production. It contains only the public table id, so it identifies a table
 * and grants nothing. The link that claims a table is different: it carries a
 * one-time token and comes from `provisionTableResponseSchema` (decision taken
 * with the pairing flow).
 */
export const tableQrResponseSchema = z.object({
  tableId: tableIdSchema,
  link: z.url(),
});
export type TableQrResponse = z.infer<typeof tableQrResponseSchema>;

// ---------------------------------------------------------------------------
// Provisioning
// ---------------------------------------------------------------------------

/**
 * Body of `POST /api/v1/admin/tables/provision`: a table that nobody owns yet.
 * The customer claims it with the QR code, so there is no `ownerAccountId`.
 */
export const provisionTableRequestSchema = createTableRequestSchema.omit({ ownerAccountId: true });
export type ProvisionTableRequest = z.input<typeof provisionTableRequestSchema>;

/**
 * The broker login of one table's controller. Shown once, never stored in clear.
 * `tls` is false only in development, against a local `mqtt://` broker: in
 * production the API refuses any other broker URL than `mqtts://` or `wss://`.
 */
export const mqttCredentialsSchema = z.object({
  host: z.string().min(1),
  port: z.number().int().min(1).max(65535),
  tls: z.boolean(),
  clientId: z.string().min(1),
  username: z.string().min(1),
  password: z.string().min(1),
});
export type MqttCredentials = z.infer<typeof mqttCredentialsSchema>;

/** A claim link with its raw token: shown once, because the server keeps only a hash. */
export const claimTokenSchema = pairingLinkSchema.extend({ token: pairingTokenSchema });
export type ClaimToken = z.infer<typeof claimTokenSchema>;

/**
 * Payload of `POST /api/v1/admin/tables/provision` (`201`).
 *
 * `mqtt` is for the Raspberry Pi and is returned once. `pairing` is for the
 * customer: its link is the only thing the QR code holds, and it holds no
 * credential.
 */
export const provisionTableResponseSchema = z.object({
  table: adminTableSchema,
  mqtt: mqttCredentialsSchema,
  pairing: claimTokenSchema,
});
export type ProvisionTableResponse = z.infer<typeof provisionTableResponseSchema>;

/**
 * Payload of `POST /api/v1/admin/tables/:tableId/claim-token` (`201`): a new claim
 * link for a table nobody owns yet, replacing the earlier one, which stops
 * working. For a printed code that expired while the table sat in stock.
 */
export const claimTokenResponseSchema = z.object({
  tableId: tableIdSchema,
  pairing: claimTokenSchema,
});
export type ClaimTokenResponse = z.infer<typeof claimTokenResponseSchema>;

// ---------------------------------------------------------------------------
// Customers
// ---------------------------------------------------------------------------

/**
 * Where a customer stands: `pending-activation` until they set a password with
 * their activation code (again after an access reset), then `active`, until an
 * admin disables them.
 */
export const customerStatusSchema = z.enum(['pending-activation', 'active', 'disabled']);
export type CustomerStatus = z.infer<typeof customerStatusSchema>;

/** A customer account as an admin sees it. Never a hash or an activation code. */
export const adminCustomerSchema = authAccountSchema.extend({
  status: customerStatusSchema,
  createdAt: z.string(),
});
export type AdminCustomer = z.infer<typeof adminCustomerSchema>;

/** Body of `POST /api/v1/admin/customers`. */
export const createCustomerRequestSchema = z.object({
  email: emailSchema,
  displayName: accountDisplayNameSchema,
});
export type CreateCustomerRequest = z.infer<typeof createCustomerRequestSchema>;

/**
 * Payload of `POST /api/v1/admin/customers` (`201`) and of
 * `POST /api/v1/admin/customers/:accountId/reset-access` (`200`).
 *
 * `activationCode` is shown here once and never again: the server keeps only
 * its hash. The admin hands it to the customer, who activates with it.
 */
export const customerAccessResponseSchema = z.object({
  account: adminCustomerSchema,
  activationCode: z.string(),
});
export type CustomerAccessResponse = z.infer<typeof customerAccessResponseSchema>;
export const createCustomerResponseSchema = customerAccessResponseSchema;
export type CreateCustomerResponse = CustomerAccessResponse;
export const resetCustomerAccessResponseSchema = customerAccessResponseSchema;
export type ResetCustomerAccessResponse = CustomerAccessResponse;

/** Payload of `GET /api/v1/admin/customers`, oldest first. */
export const listCustomersResponseSchema = z.object({
  customers: z.array(adminCustomerSchema),
});
export type ListCustomersResponse = z.infer<typeof listCustomersResponseSchema>;

/** Path parameters of `/api/v1/admin/customers/:accountId/*`. */
export const customerParamsSchema = z.object({ accountId: z.string().min(1).max(100) });
export type CustomerParams = z.infer<typeof customerParamsSchema>;

/** Payload of `POST /api/v1/admin/customers/:accountId/disable`: the customer, now disabled. */
export const disableCustomerResponseSchema = adminCustomerSchema;
export type DisableCustomerResponse = AdminCustomer;
